formulas.monsterLevel:
function monsterLevel(g){
  const pl = (g.player && g.player.level) || 1, d = g.depth || 1;
  // v379: full scaling up to 5 levels above the zone, then it drops off heavily (a quarter of a level per extra character level, never more than +1 beyond the 5)
  // v490: tapers much sooner -- an over-levelled character pulls monsters up only half a level per level (max +3 within 5 levels,
  // then +0.1 per extra level, never past +4), so old zones really do get easier. Under-levelled: monsters stay at the zone's level.
  const full = d<10 ? AREA_LEVEL_BAND_EARLY : 5;
  if(pl <= d) return d;
  const over = pl - d;
  return Math.round(d + Math.min(over, full)*0.6 + Math.min(1, Math.max(0, over-full)*0.1));
}

formulas.itemAttrReq:
function itemAttrReq(it){
  const key = itemReqAttrKey(it); if(!key) return null;
  if(it.attrReq && it.attrReq.key===key) return it.attrReq;
  const L = Math.max(1, it.ilvl || it.levelReq || 1);
  let ratio = 1;
  const base = (it.affixes||[]).find(a=>a.base);
  if(base){
    if(base.key==='wpnDmg'){ const sh = WPN_SHAPE[it.slotType]; if(sh) ratio = ((base.min+base.max)/2)/(sh.a+sh.b*L); }
    else { const m = baseStatMean(it.slotType, it.material, L); if(m>0) ratio = base.value/m; }
  }
  let f = 0.86 + 0.6*(clamp(ratio, 0.85, 1.15) - 0.9) + ({magic:0.03, rare:0.06}[it.rarity] || 0);
  f += (it.affixes||[]).filter(a=>a.key==='defensePct').reduce((t,a)=>t+(a.value||0), 0)/400;
  it.attrReq = {key, value:Math.max(1, Math.round(attrMainAtLevel(L)*clamp(f, 0.82, 1.15)))};
  return it.attrReq;
}

formulas.resCost:
function resCost(p,id,rankOverride){
  const r = RESOURCE_SKILLS[id]; if(!r) return 0;
  let c = r.cost;
  if(id==='raiseDead' && p && p.skills) return RAISE_DEAD_MANA_PER_SKEL * Math.max(1, necroSkeletonLimit(p));   // v489: 12 mana per skeleton raised
  const rk = rankOverride!=null ? rankOverride : ((p&&p.skills&&effectiveRank(p,id))||0);
  // v563: Mana and Stamina costs grow with the skill's rank, as the pools grow with Intelligence / Dexterity (never with character level);
  // Rage stays a fixed 100, so Rage skills keep their own small rank steps
  if(isRageSkill(id)){ if(r.step) c += r.step*Math.max(0,rk-1); }
  else c *= 1 + COST_PER_RANK*Math.max(0, rk-1);
  if(p && WR_SKILLS[id] && (p.windReady || p._wrCostWin>0)) c *= 0.5;   // v466 Windrunner
  if(p && p.cls==='ranger' && p.skills){ const ts=effectiveRank(p,'steadyBreathing')||0; if(ts>0) c *= 1 - 0.05*Math.min(10,ts); }   // v497: Steady Breathing is its own Marksman node
  return Math.round(c);
}

