    if(srcEnemy && srcEnemy.hp>0){ srcEnemy.hp -= applyEnemyArmor(p, srcEnemy, amt); srcEnemy.hitT = 0.15; checkExecute(g, srcEnemy); }
    p.hp = Math.min(p.maxHp, p.hp + amt*MIRROR_HEAL);
